"""Regenerates src/features/collision_viewer/shaders_spirv.h from the GLSL shaders next to it.

Based on tools/embed_shaders.py of doom-eternal-collision-viewer by IlyaTsyganov (commit 43ac57d), used with
the author's permission.

A manual step: run it after changing shaders/collision.vert or shaders/collision.frag and commit the header.
The build does not need a shader compiler.

    python scripts/embed_shaders.py                      # glslangValidator from PATH or %VULKAN_SDK%\\Bin
    python scripts/embed_shaders.py --glslang C:\\path\\glslangValidator.exe
    python scripts/embed_shaders.py --spv vert.spv frag.spv   # embed SPIR-V compiled elsewhere
"""

import argparse
import os
import shutil
import struct
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FEATURE = ROOT / 'src' / 'features' / 'collision_viewer'
SHADERS = [('kVertexShader', FEATURE / 'shaders' / 'collision.vert'),
           ('kFragmentShader', FEATURE / 'shaders' / 'collision.frag')]
HEADER = FEATURE / 'shaders_spirv.h'
SPIRV_MAGIC = 0x07230203


def find_glslang(explicit):
    if explicit:
        return explicit
    found = shutil.which('glslangValidator')
    if found:
        return found
    sdk = os.environ.get('VULKAN_SDK')
    if sdk:
        candidate = Path(sdk) / 'Bin' / 'glslangValidator.exe'
        if candidate.exists():
            return str(candidate)
    sys.exit('glslangValidator not found: install the Vulkan SDK or pass --glslang (or --spv)')


def compile_shader(glslang, source, output):
    # -V: SPIR-V for Vulkan 1.0, as the layer creates the modules on any Vulkan 1.0 device.
    subprocess.run([glslang, '-V', '--target-env', 'vulkan1.0', '-o', str(output), str(source)], check=True)


def words(data, name):
    if len(data) % 4 or len(data) < 20 or struct.unpack_from('<I', data)[0] != SPIRV_MAGIC:
        sys.exit(f'{name}: not a SPIR-V module')
    return struct.unpack('<' + 'I' * (len(data) // 4), data)


def render(modules):
    lines = [
        '// Generated by scripts/embed_shaders.py from shaders/collision.vert and shaders/collision.frag;',
        '// do not edit by hand.',
        '// Based on doom-eternal-collision-viewer by IlyaTsyganov (commit 43ac57d), used with the author\'s'
        ' permission.',
        '',
        '#pragma once',
        '',
        '#include <cstdint>',
        '',
        'namespace doomfix::cv {',
        '',
    ]
    for name, values in modules:
        lines.append(f'inline constexpr uint32_t {name}[] = {{')
        for i in range(0, len(values), 8):
            lines.append('    ' + ', '.join(f'0x{v:08x}' for v in values[i:i + 8]) + ',')
        lines.append('};')
        lines.append('')
    lines.append('}  // namespace doomfix::cv')
    return '\n'.join(lines) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('--glslang', help='path to glslangValidator')
    parser.add_argument('--spv', nargs=2, metavar=('VERT', 'FRAG'), help='embed these SPIR-V files instead')
    parser.add_argument('--output', default=str(HEADER), help='header to write (default: %(default)s)')
    args = parser.parse_args()

    modules = []
    if args.spv:
        for (name, _), path in zip(SHADERS, args.spv):
            modules.append((name, words(Path(path).read_bytes(), path)))
    else:
        glslang = find_glslang(args.glslang)
        with tempfile.TemporaryDirectory() as temp:
            for name, source in SHADERS:
                output = Path(temp) / (source.name + '.spv')
                compile_shader(glslang, source, output)
                modules.append((name, words(output.read_bytes(), str(output))))

    Path(args.output).write_text(render(modules), encoding='utf-8', newline='\n')
    print(f'wrote {args.output}: ' + ', '.join(f'{name} {len(values) * 4} bytes' for name, values in modules))


if __name__ == '__main__':
    main()
